#!/usr/bin/env python3
import collections, hashlib, json, pathlib, statistics, sys, tempfile, shutil, subprocess
REPO=pathlib.Path('/root/.codex/worktrees/f396/medaka')
ROOT=pathlib.Path('/tmp/medaka-promotion-ablation-c324af5a')
RESULTS=REPO/'test/gc_prototype/results'
EXPECTED_ARMS=['baseline','peak_only','promotion_only','combined','boehm_caller_inline','boehm_inline']
PROFILES=['ephemeral','list','tree','mutation','atomic','mixed','sizes']
REPEATS=6
DYNAMIC={'elapsed_seconds','preparation_seconds','process_peak_rss_bytes'}
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def read(path):
    records=[json.loads(x) for x in path.read_text().splitlines() if x.strip()]
    assert records and records[0]['kind']=='header'
    return records[0],records[1:]
def analyze(label):
    path=RESULTS/f'2026-10-12-promotion-5m-{label}.jsonl'
    h,rows=read(path)
    checks={}
    checks['head_is_frozen_c324']=h['git_head']=='c324af5a926c7e65a4aede0844de459616c6e8f2'
    checks['correctness_artifact_hash_matches']=h['correctness_sha256']==sha(ROOT/'correctness/result.json')
    checks['expected_6_arms_7_profiles_6_repeats']=h['arms']==EXPECTED_ARMS and h['profiles']==PROFILES and h['repeats']==REPEATS and len(rows)==len(EXPECTED_ARMS)*len(PROFILES)*REPEATS
    checks['row_keys_complete']=all(sum(x['backend']==a and x['profile']==p for x in rows)==REPEATS for a in EXPECTED_ARMS for p in PROFILES)
    checks['balanced_position_per_arm_profile']=all(sorted(x['execution_position'] for x in rows if x['backend']==a and x['profile']==p)==list(range(REPEATS)) for a in EXPECTED_ARMS for p in PROFILES)
    checks['all_six_orders_rotate_and_are_recorded']=all(len({tuple(x['execution_order']) for x in rows if x['profile']==p})==REPEATS and all(x['execution_order'][x['execution_position']]==x['backend'] for x in rows) for p in PROFILES)
    checks['allocation_payload_checksum_identity_all_42_profile_repeat_groups']=all(len({(x['sample']['allocations'],x['sample']['payload_bytes'],x['sample']['checksum']) for x in rows if x['profile']==p and x['repeat']==r})==1 for p in PROFILES for r in range(REPEATS))
    equality=[]
    for p in PROFILES:
        for r in range(REPEATS):
            group={x['backend']:x['sample'] for x in rows if x['profile']==p and x['repeat']==r}
            base=group['baseline']; keys=set().union(*(set(group[a]) for a in ('baseline','peak_only','promotion_only','combined')))-DYNAMIC
            equality.append(all({k:v for k,v in group[a].items() if k in keys}=={k:v for k,v in base.items() if k in keys} for a in ('peak_only','promotion_only','combined')))
    checks['custom_counter_memory_copy_peak_stats_equal_all_126_comparisons_per_capacity']=len(equality)==42 and all(equality)
    current={name:{q.name:sha(q) for q in sorted(pathlib.Path(src).iterdir()) if q.is_file()} for name,src in h['source_paths'].items()}
    checks['source_hashes_match_frozen_dirs']=current==h['source_sha256']
    patch_ok=True
    baseline_gc=pathlib.Path(h['source_paths']['baseline'])/'gc.c'
    for variant in ('peak_only','promotion_only','combined'):
        patch_text=h['variant_patches'][variant]['unified_diff']
        with tempfile.TemporaryDirectory(prefix='promotion-patch-audit-',dir=ROOT) as td:
            work=pathlib.Path(td); shutil.copyfile(baseline_gc,work/'gc.c')
            patchfile=work/'variant.patch'; patchfile.write_text(patch_text)
            if patch_text:
                result=subprocess.run(['patch','-s','-p1','-i',str(patchfile)],cwd=work,text=True,capture_output=True)
                patch_ok=patch_ok and result.returncode==0
            patch_ok=patch_ok and sha(work/'gc.c')==h['source_sha256'][variant]['gc.c']
    checks['variant_patches_reproduce_exact_gc_c_hashes']=patch_ok
    checks['static_libgc_boehm_comparators']=h['libgc'].get('boehm_linkage')=='static' and bool(h['libgc'].get('boehm_archive_sha256')) and all('/usr/lib/x86_64-linux-gnu/libgc.a' in h['build_commands'][a] for a in ('boehm_caller_inline','boehm_inline'))
    checks['all_checks_pass']=all(checks.values())
    per_profile={}
    for p in PROFILES:
        arms={}
        for a in EXPECTED_ARMS:
            samples=[x['sample'] for x in rows if x['backend']==a and x['profile']==p]
            elapsed=[x['elapsed_seconds'] for x in samples]
            st={'min_seconds':min(elapsed),'median_seconds':statistics.median(elapsed),'range_seconds':max(elapsed)-min(elapsed),'median_process_peak_rss_bytes':statistics.median(x['process_peak_rss_bytes'] for x in samples)}
            if a in ('baseline','peak_only','promotion_only','combined'):
                for k in ('peak_accounted_bytes','accounted_bytes','nursery_capacity_bytes','copied_bytes','copied_payload_bytes','nursery_payload_bytes','exact_live_payload_bytes','payload_bytes'):
                    if all(k in x for x in samples): st['median_'+k]=statistics.median(x[k] for x in samples)
                if all('copied_payload_bytes' in x and 'nursery_payload_bytes' in x for x in samples):
                    st['median_copied_payload_over_nursery_payload_fraction']=statistics.median(x['copied_payload_bytes']/x['nursery_payload_bytes'] for x in samples)
                else: st['median_copied_payload_over_nursery_payload_fraction']=None
                if all('exact_live_payload_bytes' in x and 'payload_bytes' in x for x in samples):
                    st['median_final_live_payload_over_total_payload_fraction']=statistics.median(x['exact_live_payload_bytes']/x['payload_bytes'] for x in samples)
                else: st['median_final_live_payload_over_total_payload_fraction']=None
            else:
                for k in ('boehm_heap_bytes','boehm_heap_minus_free_bytes','boehm_total_allocated_bytes'):
                    if all(k in x for x in samples): st['median_'+k]=statistics.median(x[k] for x in samples)
            arms[a]=st
        baseline=arms['baseline']['median_seconds']
        boehm=['boehm_caller_inline','boehm_inline']
        best_median=min(boehm,key=lambda a:arms[a]['median_seconds'])
        best_min=min(boehm,key=lambda a:arms[a]['min_seconds'])
        per_profile[p]={'arms':arms,'median_time_ratio_vs_baseline':{a:arms[a]['median_seconds']/baseline for a in EXPECTED_ARMS},'minimum_time_ratio_vs_baseline':{a:arms[a]['min_seconds']/arms['baseline']['min_seconds'] for a in EXPECTED_ARMS},'fastest_Boehm_by_median':best_median,'combined_over_fastest_Boehm_median_ratio':arms['combined']['median_seconds']/arms[best_median]['median_seconds'],'fastest_Boehm_by_min':best_min,'combined_over_fastest_Boehm_min_ratio':arms['combined']['min_seconds']/arms[best_min]['min_seconds']}
    return {'label':label,'artifact':str(path),'artifact_sha256':sha(path),'header':h,'checks':checks,'per_profile':per_profile}

def main():
    audits=[analyze('offset'),analyze('aligned')]
    checks={'both_artifacts_pass':all(a['checks']['all_checks_pass'] for a in audits),'source_hashes_identical_across_capacities':audits[0]['header']['source_sha256']==audits[1]['header']['source_sha256'],'build_commands_identical_across_capacities':audits[0]['header']['build_commands']==audits[1]['header']['build_commands'],'all_sample_rows_preserved':all(a['header']['repeats']==REPEATS for a in audits)}
    out={'experiment':'promotion-peak-ablation','date':'2026-10-12','method':'Six-arm sequential cyclic profile, 5M allocations/profile, six fresh-process repetitions per arm, nursery capacities 262136 (offset) and 262144 (aligned). Timing summaries are descriptive; do not treat as statistical significance. Custom survival is copied payload / nursery payload. Final live payload / total allocated payload is reported separately.','checks':checks,'harness_source':{'runner_sha256':sha(ROOT/'runner.py'),'runner_fulltext':(ROOT/'runner.py').read_text(),'summarizer_sha256':sha(ROOT/'summarize.py'),'summarizer_fulltext':(ROOT/'summarize.py').read_text()},'audits':audits}
    output=RESULTS/'2026-10-12-promotion-audit.json'
    if not all(checks.values()):
        print(json.dumps({'failed_checks':checks,'per_artifact':[{a['label']:[k for k,v in a['checks'].items() if not v]} for a in audits]},indent=2),file=sys.stderr)
        raise SystemExit('audit checks failed')
    output.write_text(json.dumps(out,indent=2)+'\n')
    print(json.dumps({'audit':str(output),'sha256':sha(output),'checks':checks,'artifacts':[{'label':a['label'],'sha256':a['artifact_sha256'],'checks':a['checks']} for a in audits]},indent=2))
if __name__=='__main__': main()

